#!/usr/bin/env python3
"""Render observed historical price rows; no inferred current prices/spec matching."""
import html,json,pathlib
rows=json.loads(pathlib.Path('research/phase7-20261028/official-price-catalog.json').read_text());esc=html.escape
body=[]
for r in rows:
 links=' · '.join(f'<a href="{esc(x["source_url"],quote=True)}#page=1" target="_blank" rel="noopener noreferrer">{esc(x["source_date"])} 공식 PDF 1쪽 ↗</a>' for x in r['evidence'])
 body.append(f'<tr data-generation="{r["generation_id"]}" data-year="{r["model_year"]}" data-search="{esc((r["model"]+" "+r["engine"]+" "+r["trim"]).lower(),quote=True)}"><th scope="row">볼보 {esc(r["model"])}</th><td>{r["model_year"]}년형</td><td>{esc(r["engine"])}</td><td>{esc(r["trim"])}</td><td>{r["price_krw"]:,}원</td><td>{links}</td></tr>')
page='''<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>공식 과거 신차가격표 | CarRanking</title><meta name="description" content="제조사 공식 과거 가격표의 모델연도·엔진·트림·세금 기준과 원문을 확인하세요."><link rel="canonical" href="https://carranking.kr/official-price-history.html"><link rel="stylesheet" href="/vehicle-tools.css?v=20261027b"><style>td,th{overflow-wrap:anywhere}input,select{max-width:100%}[hidden]{display:none!important}.table-wrap{overflow-x:auto}</style></head><body><header class="top"><a class="brand" href="/">CarRanking <span>자동차랭킹</span></a><nav aria-label="주 메뉴"><a href="/value-evidence.html">감가율 근거·검증 상태</a><a href="/vehicle-tools.html">사양 비교·유지비</a></nav></header><main><section class="panel"><h1>공식 과거 신차가격표</h1><p>볼보 5개 모델의 2021·2022년형 가격 26개를 제조사 공식 문서와 대조했습니다. 같은 연식·엔진·트림·가격을 반복 수록한 원문은 하나로 묶고 출처를 함께 보존했습니다.</p><p><strong>과거 공시 기본가격입니다. 현재 판매가격·실제 계약가격·중고차 시세가 아닙니다.</strong> 모든 금액은 VAT 포함, 개별소비세 인하분 미적용 기준입니다. 계약월 세율·추가 옵션·할인·보조금은 별도 확인하세요.</p><p>문서 발행일과 모델연도는 다릅니다. 2021년 10월 MY22 문서에서도 S90·XC40은 MY21로 명시되어 2021년형으로 보존했습니다. 전비·연비의 휠·옵션 사양과 자동 연결하지 않으며 감가율 계산에도 사용하지 않습니다.</p><p>가격 원문 대조일: 2026-10-28 KST · 연결된 감가율의 검증일을 갱신한 것이 아닙니다.</p><label for="priceSearch">모델·엔진·트림 찾기<input id="priceSearch" type="search" placeholder="예: S60, B6 AWD, Inscription"></label><label for="priceYear">모델연도<select id="priceYear"><option value="">전체 연도</option value="2021">2021년형</option><option value="2022">2022년형</option></select></label><button type="button" class="quiet" id="priceReset">전체 보기</button><p id="priceCount" role="status"></p></section><section class="panel"><div class="table-wrap"><table><caption>모델연도·엔진·트림별 과거 기본가격 · VAT 포함 / 개소세 인하분 미적용</caption><thead><tr><th scope="col">모델</th><th scope="col">모델연도</th><th scope="col">엔진·구동 표기</th><th scope="col">트림</th><th scope="col">기본가격</th><th scope="col">원문 발표일·출처</th></tr></thead><tbody>'''+''.join(body)+'''</tbody></table></div></section></main><footer>© CarRanking · 출처와 가격 적용 조건을 함께 확인하세요.</footer><script src="/official-price-history.js"></script></body></html>'''
pathlib.Path('official-price-history.html').write_text(page)
